-- Who gets the rows that exist now. The owner's email comes from OWNER_EMAIL of the server through the setting
-- app.owner_email, which scripts/migrate.ts sets on its connection; it is not stored anywhere and not in git.
--  * email set: the owner (created if missing) gets every existing contact and group. Notes and contact_groups
--    are not touched: they belong to a contact or a group
--  * no email, and the database holds no contacts and only the 4 untouched default groups of 0003 (or none):
--    a new installation. The 4 groups are deleted, every user gets their own on first login
--  * no email, but there is data: stop, the whole migration rolls back
DO $$
DECLARE
  v_email text := lower(nullif(btrim(current_setting('app.owner_email', true)), ''));
  v_owner_id text;
  v_untouched_defaults boolean;
BEGIN
  IF v_email IS NOT NULL THEN
    SELECT id INTO v_owner_id FROM users WHERE email = v_email;
    IF v_owner_id IS NULL THEN
      v_owner_id := gen_random_uuid()::text;
      INSERT INTO users (id, name, email, email_verified) VALUES (v_owner_id, '', v_email, true);
    END IF;
    UPDATE contacts SET owner_id = v_owner_id WHERE owner_id IS NULL;
    UPDATE groups SET owner_id = v_owner_id WHERE owner_id IS NULL;
    RETURN;
  END IF;

  SELECT count(*) = 4 AND count(*) FILTER (WHERE (name, color::text, position) IN (
    ('Семья', 'pink', 1), ('Друзья', 'green', 2), ('Знакомые', 'yellow', 3), ('Коллеги', 'blue', 4)
  )) = 4
  INTO v_untouched_defaults
  FROM groups;

  IF EXISTS (SELECT 1 FROM contacts)
    OR EXISTS (SELECT 1 FROM contact_groups)
    OR NOT (v_untouched_defaults OR NOT EXISTS (SELECT 1 FROM groups))
  THEN
    RAISE EXCEPTION 'OWNER_EMAIL is not set: existing contacts and groups need an owner';
  END IF;

  DELETE FROM groups;
END $$;--> statement-breakpoint
